267	// parseNexusURL extracts the scheme+host and repository name from a Nexus URL.
268	// e.g. "https://nexus.example.com/repository/docker-group" → ("https://nexus.example.com", "docker-group")
269	func parseNexusURL(registryURL string) (host, repoName string, err error) {
270		raw := registryURL
271		if !strings.HasPrefix(raw, "http://") && !strings.HasPrefix(raw, "https://") {
272			raw = "https://" + raw
273		}
274		u, err := url.Parse(raw)
275		if err != nil {
276			return "", "", err
277		}
278		parts := strings.SplitN(strings.TrimPrefix(u.Path, "/"), "/", 3)
279		// Expected: ["repository", "<repoName>", ...]
280		if len(parts) < 2 || parts[0] != "repository" || parts[1] == "" {
281			return "", "", fmt.Errorf("not a Nexus repository path: %q", u.Path)
282		}
283		host = u.Scheme + "://" + u.Host
284		repoName = parts[1]
285		return host, repoName, nil
286	}
