288	// cleanMemberAlias strips common suffixes (-proxy, -hosted, -local) for a friendlier display name.
289	func cleanMemberAlias(name string) string {
290		for _, suffix := range []string{"-proxy", "-hosted", "-local"} {
291			if strings.HasSuffix(name, suffix) {
292				return name[:len(name)-len(suffix)]
293			}
294		}
295		return name
296	}
