18	func init() {
19		Register(&NexusDetector{})
20	}
21	
22	// NexusDetector handles Sonatype Nexus Repository Manager group repositories.
23	// Two URL formats are supported:
24	//  1. Path-based:   https://nexus.example.com/repository/docker-group
25	//  2. Subdomain:    nexus-docker-group.example.com  (requires info.ManagementURL)
26	//
27	// Which one applies is read from the URL. Whether this detector runs at all is
28	// not: that is the declared provider's decision (§3.8, decision F).
29	type NexusDetector struct{}
30	
31	// maxNexusResponse bounds what one Nexus reply may take in memory. The replies
32	// are small JSON documents (a repository and the names of its members); the
33	// figure follows the reasoning of the catalog page cap and is not measured.
34	const maxNexusResponse = 1 << 20
35	
36	// errEmptyReply and errNoRepositoryType mark a 200 reply that is not a
37	// repository document. Both fail the discovery: reading either as "not a group"
38	// would be cached (D23) and erase the members last known.
39	var (
40		errEmptyReply       = errors.New("empty reply")
41		errNoRepositoryType = errors.New("reply names no repository type")
42	)
43	
44	// nexusHTTPClient refuses a redirect to another origin, so the account of the
45	// registry is never sent to a host it was not given for.
46	var nexusHTTPClient = &http.Client{Timeout: 8 * time.Second, CheckRedirect: oci.RefuseOffOriginRedirect}
47	
48	// Provider returns the provider this detector serves.
49	func (n *NexusDetector) Provider() string { return ProviderNexus }
50	
51	// DetectGroup calls the Nexus REST API to determine whether the registry points
52	// to a group repository and, if so, returns its member repositories.
53	//
54	// Returns nil, nil when the manager answered and the repository is not a group,
55	// and an error when it could not be asked. Those two are not the same thing:
56	// the caller caches the first and must not cache the second, or one unreachable
57	// minute erases what was last known (D23).
58	func (n *NexusDetector) DetectGroup(ctx context.Context, info RegistryInfo) ([]GroupMember, error) {
59		// Resolve which URL to use for the Nexus API call.
60		apiBase := info.ManagementURL
61		if apiBase == "" {
62			apiBase = info.URL
63		}
64	
65		host, repoName, err := parseNexusURL(apiBase)
66		if err != nil {
67			// Not an error: a URL that is not a Nexus repository path is a settled
68			// answer, not a failure to reach one.
69			// The cause only: a URL that does not parse may hold a password, and
70			// url.Error repeats it whole.
71			var ue *url.Error
72			if errors.As(err, &ue) {
73				err = ue.Err
74			}
75			log.Printf("INFO [registrymgr/nexus] cannot parse Nexus URL: %v", err)
76			return nil, nil
77		}
78	
79		hasAuth := info.Username != "" && info.Password != ""
80		log.Printf("INFO [registrymgr/nexus] detecting group for %q (auth=%v)", repoName, hasAuth)
81	
82		// Step 1: generic endpoint — confirms this repo is a group, gets its format,
83		// and may already include memberNames in the attributes field (no admin privilege needed).
84		repoType, repoFormat, members, err := n.fetchRepoMeta(ctx, host, repoName, info)
85		if err != nil {
86			return nil, err
87		}
88		if repoType != "group" {
89			return nil, nil
90		}
91	
92		if len(members) > 0 {
93			log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from generic endpoint)", repoName, repoFormat, len(members))
94			return members, nil
95		}
96	
97		// Step 2: format-specific endpoint — requires nx-repository-admin privilege
98		// but returns memberNames reliably on Nexus instances that support it.
99		members = n.fetchGroupMembers(ctx, host, repoName, repoFormat, info)
100		log.Printf("INFO [registrymgr/nexus] group %q (%s) has %d members (from format endpoint)", repoName, repoFormat, len(members))
101		return members, nil
102	}
103	
104	// fetchRepoMeta calls the generic /v1/repositories/{name} endpoint.
105	// Returns type, format and any memberNames found in attributes, or an error when
106	// the manager could not be asked.
107	// Some Nexus deployments include memberNames in attributes.group without requiring admin privilege.
108	func (n *NexusDetector) fetchRepoMeta(ctx context.Context, host, repoName string, info RegistryInfo) (repoType, format string, members []GroupMember, err error) {
109		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s", host, repoName)
110		body, err := n.nexusGET(ctx, endpoint, info)
111		if err != nil {
112			log.Printf("INFO [registrymgr/nexus] meta unreachable %q: %v", endpoint, err)
113			return "", "", nil, fmt.Errorf("reading %s: %w", endpoint, err)
114		}
115		if len(bytes.TrimSpace(body)) == 0 {
116			log.Printf("INFO [registrymgr/nexus] meta %q: empty reply", repoName)
117			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errEmptyReply)
118		}
119		var result struct {
120			Type   string `json:"type"`
121			Format string `json:"format"`
122			Group  struct {
123				MemberNames []string `json:"memberNames"`
124			} `json:"group"`
125			Attributes struct {
126				Group struct {
127					MemberNames []string `json:"memberNames"`
128				} `json:"group"`
129			} `json:"attributes"`
130		}
131		if err := json.Unmarshal(body, &result); err != nil {
132			log.Printf("INFO [registrymgr/nexus] meta parse error for %q: %v", repoName, err)
133			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, err)
134		}
135		if result.Type == "" {
136			// Valid JSON that is not a repository document: `{}`, `null`.
137			log.Printf("INFO [registrymgr/nexus] meta %q: reply names no repository type", repoName)
138			return "", "", nil, fmt.Errorf("parsing the reply from %s: %w", endpoint, errNoRepositoryType)
139		}
140		log.Printf("INFO [registrymgr/nexus] meta %q: type=%s format=%s", repoName, result.Type, result.Format)
141	
142		// Collect memberNames from whichever field Nexus populated.
143		rawNames := result.Group.MemberNames
144		if len(rawNames) == 0 {
145			rawNames = result.Attributes.Group.MemberNames
146		}
147		members = memberList(info.URL, rawNames)
148		return result.Type, result.Format, members, nil
149	}
150	
151	// fetchGroupMembers calls the format-specific group endpoint which reliably
152	// includes memberNames: GET /v1/repositories/{format}/group/{name}
153	// Requires nx-repository-admin privilege; falls back to anonymous when credentials fail.
154	func (n *NexusDetector) fetchGroupMembers(ctx context.Context, host, repoName, format string, info RegistryInfo) []GroupMember {
155		if format == "" {
156			format = "docker"
157		}
158		endpoint := fmt.Sprintf("%s/service/rest/v1/repositories/%s/group/%s", host, format, repoName)
159		body, err := n.nexusGET(ctx, endpoint, info)
160		if err != nil {
161			// When auth is present but the request fails, retry anonymously.
162			// Some Nexus instances allow anonymous read of the group admin endpoint.
163			// A refused redirect to another origin is not such a failure: the
164			// detection stops there (DEVDESK-412), no silent anonymous retry.
165			if info.Username != "" && info.Password != "" && !errors.Is(err, oci.ErrOffOriginRedirect) {
166				anonInfo := RegistryInfo{URL: info.URL, ManagementURL: info.ManagementURL}
167				body, err = n.nexusGET(ctx, endpoint, anonInfo)
168			}
169		}
170		if errors.Is(err, oci.ErrOffOriginRedirect) {
171			// The advice below is for an account Nexus refused, not for this.
172			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — redirect to another origin refused (the registry URL may need to be the one Nexus serves)", endpoint, err)
173			return nil
174		}
175		if err != nil {
176			log.Printf("INFO [registrymgr/nexus] members unreachable %q: %v — account may lack nx-repository-admin privilege; run 'docker login %s' with an admin account", endpoint, err, host)
177			return nil
178		}
179		var result struct {
180			Group struct {
181				MemberNames []string `json:"memberNames"`
182			} `json:"group"`
183		}
184		if err := json.Unmarshal(body, &result); err != nil {
185			return nil
186		}
187		return memberList(info.URL, result.Group.MemberNames)
188	}
