487	// detectRegistryGroupCmd calls the generic registrymgr.DetectGroup to determine
488	// whether reg is a group repository and enumerate its members.
489	// Always emits RegistryGroupDetectedMsg (Members==nil means not a group).
490	func detectRegistryGroupCmd(reg config.RegistryItem, password string) tea.Cmd {
491		return func() tea.Msg {
492			ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
493			defer cancel()
494	
495			username := reg.Username
496			// D12: a registry the user marked anonymous is probed anonymously.
497			// Docker keys credentials by host, so without this gate the credentials
498			// stored for any registry on that host went out to all of them — which,
499			// for a Nexus instance, is every repository it serves.
500			if config.UsesCredentials(config.ResolveAuthMode(reg, nil)) {
501				username, password = discoveryCreds(reg, username, password)
502			} else {
503				username, password = "", ""
504			}
505	
506			info := registrymgr.RegistryInfo{
507				Provider:      reg.Provider,
508				URL:           reg.URL,
509				ManagementURL: reg.ManagementURL,
510				Username:      username,
511				Password:      password,
512			}
513			members, err := registrymgr.DetectGroup(ctx, info)
514			if err == nil {
515				cacheGroupMembers(reg.Slug, members)
516			}
517			return RegistryGroupDetectedMsg{RegistryURL: reg.URL, Slug: reg.Slug, Members: members, Err: err}
518		}
519	}
