46	// StatusSource says which endpoint answered with a non-success status.
47	type StatusSource int
48	
49	const (
50		// SourceRegistry is the registry's v2 API.
51		SourceRegistry StatusSource = iota
52		// SourceToken is the Bearer token endpoint.
53		SourceToken
54		// SourceManagementAPI is a registry manager's own REST API (Nexus
55		// /service/rest), not the distribution v2 API.
56		SourceManagementAPI
57	)
58	
59	// StatusError is a registry, token or management API endpoint answering with a
60	// non-success status. Failures that are not a status (unreadable body, missing
61	// realm, no token field) are plain errors.
62	type StatusError struct {
63		Code   int
64		Source StatusSource
65		// Challenge is the Www-Authenticate header of a 401 whose challenge is not
66		// Bearer; empty otherwise.
67		Challenge string
68		// unexpectedChallenge tells that 401 apart from a 401 answered after a
69		// token exchange, so Error() keeps both historical messages.
70		unexpectedChallenge bool
71	}
72	
73	// Error returns the message the plain errors carried before the type existed.
74	func (e *StatusError) Error() string {
75		switch {
76		case e.Source == SourceToken:
77			return fmt.Sprintf("token endpoint returned %d", e.Code)
78		case e.Source == SourceManagementAPI:
79			return fmt.Sprintf("management API returned %d", e.Code)
80		case e.unexpectedChallenge:
81			return fmt.Sprintf("unexpected auth challenge: %s", e.Challenge)
82		}
83		return fmt.Sprintf("registry returned %d", e.Code)
84	}
