192	// D23, fixed. A manager that cannot be asked used to be reported exactly like
193	// one that answered "not a group" — `fetchRepoMeta` returned a bare ok=false and
194	// `DetectGroup` turned both into nil, nil. Harmless while the answer was thrown
195	// away on every open; not harmless once it is cached, since one unreachable
196	// minute would erase what was last known.
197	//
198	// Its sibling above pins the other half: a real "not a group" is still not an
199	// error, so this cannot pass by making every answer one.
200	func TestAManagerThatCannotBeAskedIsAnError(t *testing.T) {
201		for _, tc := range []struct {
202			name    string
203			handler http.HandlerFunc
204		}{
205			{"the manager refuses", func(w http.ResponseWriter, _ *http.Request) {
206				w.WriteHeader(http.StatusInternalServerError)
207			}},
208			{"the reply is not JSON", func(w http.ResponseWriter, _ *http.Request) {
209				_, _ = w.Write([]byte("<html>login</html>"))
210			}},
211		} {
212			srv := httptest.NewServer(tc.handler)
213	
214			reg := config.RegistryItem{URL: srv.URL + "/repository/docker-group", Provider: config.ProviderNexus}
215			msg := run(t, detectRegistryGroupCmd(reg, "")).(RegistryGroupDetectedMsg)
216			srv.Close()
217	
218			if msg.Err == nil {
219				t.Errorf("%s: reported as a settled 'not a group', which a cache would then store", tc.name)
220			}
221			if msg.Members != nil {
222				t.Errorf("%s: Members = %+v, want none", tc.name, msg.Members)
223			}
224		}
225	}
