227	// Docker stores credentials by hostname, and a repository manager's API may
228	// live on a different host than the registry. The lookup for the management URL
229	// therefore has to be made against its host alone, with the repository path
230	// stripped — otherwise nothing matches and the probe goes out anonymous.
231	func TestManagementCredentialsAreLookedUpByHostAlone(t *testing.T) {
232		var gotUser string
233		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
234			gotUser, _, _ = r.BasicAuth()
235			_, _ = w.Write([]byte(`{"type":"group","format":"docker",
236				"attributes":{"group":{"memberNames":["dhi-proxy"]}}}`))
237		}))
238		defer srv.Close()
239	
240		host, err := url.Parse(srv.URL)
241		if err != nil {
242			t.Fatalf("parsing the test server URL: %v", err)
243		}
244		writeDockerConfig(t, map[string]any{
245			"auths": map[string]any{
246				host.Scheme + "://" + host.Host: map[string]string{"auth": encodeAuth("nexus-admin", "s3cret")},
247			},
248		})
249	
250		reg := config.RegistryItem{
251			URL:           "registry.example.com/repository/docker-group",
252			ManagementURL: srv.URL + "/repository/docker-group",
253			AuthMode:      config.AuthCredentials,
254			Provider:      config.ProviderNexus,
255		}
256		msg := run(t, detectRegistryGroupCmd(reg, "")).(RegistryGroupDetectedMsg)
257	
258		if msg.Err != nil {
259			t.Fatalf("Err = %v", msg.Err)
260		}
261		if gotUser != "nexus-admin" {
262			t.Errorf("the probe authenticated as %q, want the credentials stored for the management host", gotUser)
263		}
264		if len(msg.Members) != 1 {
265			t.Errorf("Members = %+v, want the one member", msg.Members)
266		}
267	}
