269	// D12, fixed. Docker keys credentials by host, so one `docker login` against a
270	// Nexus instance made every repository it serves authenticate as that user —
271	// including the ones the user had marked as needing no authentication, because
272	// nothing on this path ever read the flag. The mode is now read before the
273	// lookup, and the probe goes out with nothing.
274	//
275	// Its sibling above proves the lookup still happens when the mode allows it, so
276	// this one cannot pass by breaking credentials outright.
277	func TestAnAnonymousRegistryIsProbedWithoutCredentials(t *testing.T) {
278		var authenticated bool
279		srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
280			_, _, authenticated = r.BasicAuth()
281			_, _ = w.Write([]byte(`{"type":"group","format":"docker",
282				"attributes":{"group":{"memberNames":["dhi-proxy"]}}}`))
283		}))
284		defer srv.Close()
285	
286		host, err := url.Parse(srv.URL)
287		if err != nil {
288			t.Fatalf("parsing the test server URL: %v", err)
289		}
290		writeDockerConfig(t, map[string]any{
291			"auths": map[string]any{
292				host.Scheme + "://" + host.Host: map[string]string{"auth": encodeAuth("nexus-admin", "s3cret")},
293			},
294		})
295	
296		reg := config.RegistryItem{
297			URL:           srv.URL + "/repository/docker-group",
298			ManagementURL: srv.URL + "/repository/docker-group",
299			AuthMode:      config.AuthAnonymous,
300			Provider:      config.ProviderNexus,
301		}
302		msg := run(t, detectRegistryGroupCmd(reg, "")).(RegistryGroupDetectedMsg)
303	
304		if authenticated {
305			t.Error("the probe sent the credentials stored for the host to a registry marked anonymous")
306		}
307		if msg.Err != nil {
308			t.Fatalf("Err = %v — anonymous is not an error", msg.Err)
309		}
310		if len(msg.Members) != 1 {
311			t.Errorf("Members = %+v, want the detection to have run anyway", msg.Members)
312		}
313	}
